//! Detached Attr factories retain genuine owner and document-specific case.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn element_name_units_local_factories_live_tag_views_clone_and_selector_identity_are_exact(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var html=document.implementation.createHTMLDocument('owner'),xml=document.implementation.createDocument(null,'Root'),raw='A\ud800',replacement='A\ufffd';for(var owner of [document,html,xml]){var node=owner.createElement(raw),literal=null;try{literal=owner.createElement(replacement);}catch(e){throw (owner===document?'main':owner===html?'html':'xml')+':'+e.name+':'+e.message;}var parent=owner===document?document.getElementById('mount'):owner===html?html.body:xml.documentElement,expected=owner===xml?raw:'a\ud800';node.setAttribute('id','raw');literal.setAttribute('id','literal');node.appendChild(owner.createTextNode('actual'));parent.appendChild(node);parent.appendChild(literal);var live=parent.getElementsByTagName(raw),other=parent.getElementsByTagName(replacement);if(node.localName!==expected||node.tagName!==raw||node.nodeName!==raw||node.prefix!==null||node.namespaceURI!==(owner===xml?null:'http://www.w3.org/1999/xhtml')||node.ownerDocument!==owner||live.length!==1||live[0]!==node||other.length!==1||other[0]!==literal)throw 'actual raw local fields and exact live filter';var clone=node.cloneNode(true);if(clone===node||clone.localName!==expected||clone.tagName!==raw||clone.textContent!=='actual'||clone.ownerDocument!==owner)throw 'real copied local units';if(owner!==xml&&(parent.querySelector('A\ufffd')!==literal||parent.querySelector('#raw')!==node))throw 'CSS scalar replacement is not raw local identity';parent.removeChild(node);if(live.length!==0||other[0]!==literal||node.localName!==expected)throw 'saved raw-name collection remains live';}
"#);
}
#[test]
fn element_name_units_namespace_prefix_xml_factory_and_pure_svg_leaves_are_real(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument(null,''),parent=xml.createElementNS('http://www.w3.org/1999/xhtml','div'),prefix='P\ud800',local='Lo\udfff',qualified=prefix+':'+local,namespaces=['http://www.w3.org/1999/xhtml','http://www.w3.org/2000/svg','urn:element','\ud800'];for(var ns of namespaces){var node=xml.createElementNS(ns,qualified);parent.appendChild(node);if(node.prefix!==prefix||node.localName!==local||node.tagName!==qualified||node.nodeName!==qualified||node.namespaceURI!==ns||node.ownerDocument!==xml)throw 'genuine QName and URI units';var copy=node.cloneNode(false);if(copy===node||copy.prefix!==prefix||copy.localName!==local||copy.namespaceURI!==ns||copy.ownerDocument!==xml)throw 'exact namespace leaf clone';}if(parent.getElementsByTagName(qualified).length!==4||parent.getElementsByTagName('P\ufffd:Lo\ufffd').length)throw 'qualified live filter never uses scalar projection';var rootDoc=document.implementation.createDocument('http://www.w3.org/1999/xhtml',qualified),root=rootDoc.documentElement;if(root.prefix!==prefix||root.localName!==local||root.tagName!==qualified||root.ownerDocument!==rootDoc||rootDoc.getElementsByTagName(qualified)[0]!==root)throw 'actual XML factory root name';var html=document.createElementNS('http://www.w3.org/1999/xhtml','p\ud800:span');if(html.prefix!=='p\ud800'||html.localName!=='span'||html.tagName!=='P\ud800:SPAN')throw 'HTML qualified uppercase preserves raw prefix';var plain=xml.createElement('P\ud800:Lo\udfff');if(plain.prefix!==null||plain.localName!=='P\ud800:Lo\udfff'||plain.namespaceURI!==null)throw 'createElement local colon is not namespace prefix';
"#);assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());let(a,b,c)=page.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());
}
#[test]
fn element_name_units_ordered_validation_brand_and_namespace_guards_publish_no_prefix(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument(null,''),order='',caught=false;try{xml.createElementNS({toString:function(){order+='n';return 'urn:element';}},{toString:function(){order+='q';return '\ud800:bad name';}});}catch(e){caught=e instanceof DOMException&&e.name==='InvalidCharacterError';}if(!caught||order!=='nq'||xml.documentElement!==null)throw 'ordered raw QName validation';caught=false;try{document.createElement('A\ud800 bad');}catch(e){caught=e instanceof DOMException&&e.name==='InvalidCharacterError';}if(!caught)throw 'ordinary raw local invalid characters';caught=false;try{xml.createElementNS(null,'\ud800:Local');}catch(e){caught=e instanceof DOMException&&e.name==='NamespaceError';}if(!caught)throw 'raw prefix needs actual namespace';var valid=xml.createElementNS('urn:element','xml\ud800:Local');if(valid.prefix!=='xml\ud800'||valid.namespaceURI!=='urn:element')throw 'raw prefix is not reserved XML spelling';var local=document.createElement('A\ud800=valid');if(local.localName!=='a\ud800=valid')throw 'current alpha-start local-name rule retains equal';
"#);
}

#[test]
fn element_name_units_inert_svg_edges_refuse_native_activation_before_any_prefix_then_recover(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var owner=document.implementation.createHTMLDocument('owner'),fragment=owner.createDocumentFragment(),prefix=owner.createElement('span'),root=owner.createElement('div'),rect=owner.createElementNS('http://www.w3.org/2000/svg','rect'),mount=document.getElementById('mount');rect.setAttribute('width','2');rect.setAttribute('height','3');root.appendChild(rect);fragment.appendChild(prefix);fragment.appendChild(root);var watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});var caught=false;try{mount.appendChild(fragment);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||mount.childNodes.length||fragment.childNodes.length!==2||fragment.firstChild!==prefix||root.firstChild!==rect||root.ownerDocument!==owner||watch.takeRecords().length)throw 'legal inert data cannot bypass SVG edge activation';
"#);let Value::Host(fragment)=page.runtime.execute("fragment",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("fragment")};let mount=(0..doc.nodes.len()).find(|&n|doc.attr(n,"id")==Some("mount")).unwrap();page.begin_job();let before=(page.state.retained,page.state.dom_commits,doc.nodes.len(),doc.nodes[mount].children.clone());assert!(Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}.splice_checked_inert_fragment(mount,fragment,None).unwrap_err().contains("SVG"));assert_eq!((page.state.retained,page.state.dom_commits,doc.nodes.len(),doc.nodes[mount].children.clone()),before);
 run(&mut doc,&mut forms,&mut page,r#"var svg=owner.createElementNS('http://www.w3.org/2000/svg','svg');svg.appendChild(rect);root.appendChild(svg);if(mount.appendChild(fragment)!==fragment||mount.childNodes.length!==2||root.ownerDocument!==document||svg.firstChild!==rect||rect.ownerDocument!==document||fragment.childNodes.length)throw 'safe native SVG hierarchy recovers with same records';"#);assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());let(a,b,c)=page.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());
}
#[test]
fn element_name_units_saved_child_origin_revalidates_before_factory_or_raw_filter_conversion(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var owner=document.implementation.createHTMLDocument('owner'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var create=frame.contentWindow.Function('doc','ns','name','return doc.createElementNS(ns,name);'),query=frame.contentWindow.Element.prototype.getElementsByTagName,calls=0,ns={toString:function(){calls++;return 'http://www.w3.org/1999/xhtml';}},name={toString:function(){calls++;return 'a\ud800';}},node=create(owner,ns,name);owner.body.appendChild(node);if(node.localName!=='a\ud800'||query.call(owner.body,name)[0]!==node||calls!==3)throw 'genuine child realm exact name and query';
"#);page.set_location(&crate::navigation::address("https://other-element-units.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.dom_commits);for expression in ["create(owner,ns,name);","query.call(owner.body,name);"]{assert_eq!(page.console_eval(&mut doc,&mut forms,expression).errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.dom_commits),before);}run(&mut doc,&mut forms,&mut page,"if(calls!==3||node.localName!=='a\\ud800')throw 'origin before name conversion';");
}
